<template><div class="login-page"><div class="login-brand"><div class="logo">J</div><h1>JMOM 自动化测试平台</h1><p>场景、数据、执行和证据，一站式完成。</p></div><el-card class="login-card"><h2>欢迎回来</h2><p>登录后开始执行自动化测试</p><el-form :model="form" @submit.prevent="submit"><el-form-item label="账号"><el-input v-model="form.username" size="large"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password size="large"/></el-form-item><el-alert v-if="error" :title="error" type="error" show-icon :closable="false"/><el-button type="primary" size="large" native-type="submit" :loading="loading" class="login-button">登录平台</el-button></el-form></el-card></div></template>
<script setup>import{reactive,ref}from'vue';import{usePlatformStore}from'../stores/platform';const store=usePlatformStore(),loading=ref(false),error=ref(''),form=reactive({username:'tester',password:'Tester123!'});async function submit(){loading.value=true;error.value='';try{await store.login(form)}catch(e){error.value=e.message}finally{loading.value=false}}</script>
